package dev.redstoneengineering.block;
import com.mojang.serialization.MapCodec;import dev.redstoneengineering.RedstoneEngineering;import dev.redstoneengineering.physics.DomainNetwork;import dev.redstoneengineering.physics.RuntimeIntStore;import net.minecraft.core.BlockPos;import net.minecraft.core.Direction;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.BlockGetter;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.phys.BlockHitResult;
/** Redstone-like resonance dust: automatic N/E/S/W topology, runtime f/A payload. */
public class AmethystResonanceDustBlock extends SurfaceTraceBlock{private static final String KEY="amethyst_trace";public AmethystResonanceDustBlock(Properties p){super(p);}@Override public MapCodec<AmethystResonanceDustBlock> codec(){return RedstoneEngineering.AMETHYST_RESONANCE_DUST_CODEC.value();}@Override protected boolean canConnectTo(BlockGetter l,BlockPos p,Direction d,BlockState n){return d.getAxis()!=Direction.Axis.Y&&TransmissionTopology.amethystPort(n,d);}public static void setResonance(Level l,BlockPos p,int f,int a){int[]r=RuntimeIntStore.get(l,KEY,p,2);r[0]=a>0?Math.max(1,Math.min(15,f)):0;r[1]=Math.max(0,Math.min(15,a));}public static boolean active(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,2)[1]>0;}public static int frequency(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,2)[0];}public static int amplitude(Level l,BlockPos p){return RuntimeIntStore.get(l,KEY,p,2)[1];}@Override protected void neighborChanged(BlockState s,Level l,BlockPos p,net.minecraft.world.level.block.Block b,BlockPos np,boolean m){super.neighborChanged(s,l,p,b,np,m);if(l instanceof ServerLevel sl)DomainNetwork.recomputeAmethyst(sl,p);}@Override protected void onPlace(BlockState s,Level l,BlockPos p,BlockState o,boolean m){super.onPlace(s,l,p,o,m);if(l instanceof ServerLevel sl)DomainNetwork.recomputeAmethyst(sl,p);}@Override protected void onRemove(BlockState s,Level l,BlockPos p,BlockState ns,boolean m){if(!s.is(ns.getBlock()))RuntimeIntStore.remove(l,KEY,p);super.onRemove(s,l,p,ns,m);}@Override protected InteractionResult useWithoutItem(BlockState s,Level l,BlockPos p,Player pl,BlockHitResult h){if(!l.isClientSide)pl.displayClientMessage(Component.literal("Amethyst resonance dust | "+(active(l,p)?"EVENT":"idle")+" | f="+frequency(l,p)+" | A="+amplitude(l,p)+"/15"),true);return InteractionResult.sidedSuccess(l.isClientSide);}}
